(r, big) => {
    const n = big ? 1000 : r.int(2, 9);
    const vals = r.distinct(n, big ? -1000000000 : -20, big ? 1000000000 : 20);
    const nodes = [];
    let root = null;
    for (const v of vals) {
      const nd = { v, l: null, r: null };
      if (!root) root = nd;
      else {
        let c = root;
        for (;;) {
          if (v < c.v) { if (c.l) c = c.l; else { c.l = nd; break; } }
          else { if (c.r) c = c.r; else { c.r = nd; break; } }
        }
      }
      nodes.push(nd);
    }
    const i = r.int(0, n - 1); let j = r.int(0, n - 2); if (j >= i) j++;
    const t = nodes[i].v; nodes[i].v = nodes[j].v; nodes[j].v = t;
    const out = [], q = [root]; let qi = 0;
    while (qi < q.length) { const x = q[qi++]; if (x) { out.push(x.v); q.push(x.l, x.r); } else out.push(null); }
    while (out[out.length - 1] === null) out.pop();
    return [out];
  }

