function fixSwappedTree(root: TreeNode | null): void {
  const nodes: TreeNode[] = [], stack: TreeNode[] = [];
  let cur = root;
  while (cur || stack.length) {
    while (cur) { stack.push(cur); cur = cur.left; }
    cur = stack.pop()!;
    nodes.push(cur);
    cur = cur.right;
  }
  const vals = nodes.map(n => n.val).sort((a, b) => a - b);
  nodes.forEach((n, i) => { n.val = vals[i]; });
}

