function fixSwappedTree(root: TreeNode | null): void {
  let first: TreeNode | null = null, second: TreeNode | null = null, prev: TreeNode | null = null;
  const visit = (node: TreeNode) => {
    if (prev && prev.val > node.val) {
      if (!first) first = prev;
      second = node;
    }
    prev = node;
  };
  let cur = root;
  while (cur) {
    if (!cur.left) { visit(cur); cur = cur.right; continue; }
    let pre = cur.left;
    while (pre.right && pre.right !== cur) pre = pre.right;
    if (!pre.right) { pre.right = cur; cur = cur.left; } // thread back, go left
    else { pre.right = null; visit(cur); cur = cur.right; } // left side done
  }
  const t = first!.val; first!.val = second!.val; second!.val = t;
}

